import hashlib

SECRET = "training-secret-key"
NOW = 1_700_000_000


def sign(payload):
    return hashlib.sha256(f"{SECRET}|{payload}".encode()).hexdigest()[:12]


def mint(user, exp):
    payload = f"{user}:{exp}"
    return f"{payload}.{sign(payload)}"


REVOKED = {mint("carol", NOW + 3600)}

REQUESTS = [
    ("r1", mint("alice", NOW + 3600)),
    ("r2", mint("alice", NOW + 3600)[:-1] + "x"),
    ("r3", mint("bob", NOW - 60)),
    ("r4", mint("carol", NOW + 3600)),
    ("r5", "not-a-token"),
]


def verify(token, now, revoked):
    if token.count(".") != 1 or ":" not in token.split(".")[0]:
        return (False, "MALFORMED", None)
    payload, sig = token.split(".")
    if sign(payload) != sig:
        return (False, "BAD_SIGNATURE", None)
    user, exp = payload.rsplit(":", 1)
    if now >= int(exp):
        return (False, "EXPIRED", None)
    if token in revoked:
        return (False, "REVOKED", None)
    return (True, "OK", user)


accepted = 0
for name, token in REQUESTS:
    ok, reason, user = verify(token, NOW, REVOKED)
    if ok:
        accepted += 1
        print(f"{name}: ACCEPT user={user}")
    else:
        print(f"{name}: REJECT reason={reason}")
print(f"accepted={accepted} rejected={len(REQUESTS) - accepted}")

