import hashlib
import hmac

SECRET = b"cookie-signing-secret"
REVOKED = set()


def sign(payload):
    return hmac.new(SECRET, payload.encode(), hashlib.sha256).hexdigest()[:16]


def mint(user, exp):
    payload = f"{user}.{exp}"
    return f"{payload}.{sign(payload)}"


def set_cookie_header(token):
    return f"Set-Cookie: sid={token}; HttpOnly; Secure; SameSite=Strict"


def validate(token, now):
    parts = token.split(".")
    if len(parts) != 3:
        return (401, "MALFORMED")
    user, exp, sig = parts
    if not hmac.compare_digest(sign(f"{user}.{exp}"), sig):
        return (401, "BAD_SIGNATURE")
    if now >= int(exp):
        return (401, "EXPIRED")
    if sig in REVOKED:
        return (401, "REVOKED")
    return (200, user)


allowed = 0
denied = 0


def request(t, label, tok):
    global allowed, denied
    status, detail = validate(tok, t)
    if status == 200:
        allowed += 1
        print(f"t={t} GET /account ({label}) -> 200 user={detail}")
    else:
        denied += 1
        print(f"t={t} GET /account ({label}) -> 401 {detail} audit=deny")


token = mint("alice", 2000)
print(set_cookie_header(token))
request(1200, "fresh", token)
request(1300, "tampered", token[:-1] + ("x" if token[-1] != "x" else "y"))
REVOKED.add(token.split(".")[2])
print("t=1500 POST /logout -> sid signature revoked server-side")
request(1600, "replay after logout", token)
request(2100, "past expiry", mint("alice", 2000))
print(f"allowed={allowed} denied={denied}")

