def path_cost(node):
    if "cost" in node:
        return node["cost"]
    child_costs = [path_cost(c) for c in node["children"]]
    return sum(child_costs) if node["op"] == "AND" else min(child_costs)


def cheapest_child(or_node):
    return min(or_node["children"], key=path_cost)


