def review_handler(name, src):
    takes_object_id = re.search(r"def\s+\w+\([^)]*\b\w+_id\b", src) is not None
    scoped = "owner_id=" in src
    untrusted = any(s in src for s in ("request.headers", "request.args", "request.json"))
    audited = ("audit.log" in src) or ("audit.write" in src)
    if not takes_object_id:
        return ("APPROVE", "no object access to authorize")
    if untrusted:
        return ("BLOCK", "untrusted scope: authz input from a client-controlled field")
    if not scoped:
        return ("BLOCK", "IDOR: id-selected fetch not scoped to caller")
    if not audited:
        return ("WARN", "scoped but denial not audited")
    return ("APPROVE", "object access scoped and audited")


