import hashlib


def integrity(content):
    return "sha256-" + hashlib.sha256(content.encode()).hexdigest()


_TRUSTED = {
    "leftpad": "content-of-leftpad-1.3.0",
    "asyncio-helper": "content-of-asyncio-helper-2.1.0",
    "color-log": "content-of-color-log-0.4.2",
}


def _mk_lockfile():
    return {name: integrity(c) for name, c in _TRUSTED.items()}


RESOLVED = [
    {"name": "leftpad", "content": "content-of-leftpad-1.3.0", "postinstall": False},
    {"name": "asyncio-helper", "content": "content-of-asyncio-helper-2.1.0", "postinstall": False},
    {"name": "color-log", "content": "content-of-color-log-0.4.2-PWNED", "postinstall": True},
]


def verify_package(name, content, lockfile):
    if name not in lockfile:
        return (False, "unpinned")
    if integrity(content) != lockfile[name]:
        return (False, "hash-mismatch")
    return (True, "verified")


def install(packages, lockfile):
    scripts_run = 0
    scripts_blocked = 0
    verdict = "OK"
    for pkg in packages:
        ok, reason = verify_package(pkg["name"], pkg["content"], lockfile)
        print(f"{pkg['name']:<16} {reason}")
        if ok:
            if pkg["postinstall"]:
                scripts_run += 1
        else:
            verdict = "DENIED"
            if pkg["postinstall"]:
                scripts_blocked += 1
    return (verdict, scripts_run, scripts_blocked)


