def matches(pattern, value):
    if pattern.endswith("*"):
        return value.startswith(pattern[:-1])
    return pattern == value


def evaluate(policy, action, resource):
    for stmt in policy:
        if matches(stmt["action"], action) and matches(stmt["resource"], resource):
            return "ALLOW"
    return "DENY"


def blast_radius(policy, attempts):
    return sum(1 for action, resource in attempts if evaluate(policy, action, resource) == "ALLOW")


for action, resource in ATTEMPTS:
    print(f"{evaluate(POLICY, action, resource):<5} {action:<15} {resource}")
print(f"blast radius (allowed of {len(ATTEMPTS)} attempts): {blast_radius(POLICY, ATTEMPTS)}")

