EVENTS = [
    {"actor": "u1", "decision": "DENY", "ts": 10},
    {"actor": "u1", "decision": "DENY", "ts": 200},
    {"actor": "u1", "decision": "ALLOW", "ts": 205},
    {"actor": "u7", "decision": "DENY", "ts": 100},
    {"actor": "u7", "decision": "DENY", "ts": 101},
    {"actor": "u7", "decision": "DENY", "ts": 102},
    {"actor": "u7", "decision": "DENY", "ts": 103},
    {"actor": "u7", "decision": "DENY", "ts": 104},
    {"actor": "u7", "decision": "ALLOW", "ts": 106},
]


def detect(events, window, threshold):
    by_actor = {}
    for e in events:
        if e["decision"] == "DENY":
            by_actor.setdefault(e["actor"], []).append(e["ts"])
    alerts = []
    for actor, times in by_actor.items():
        times.sort()
        best = 0
        for i in range(len(times)):
            count = sum(1 for t in times if times[i] <= t < times[i] + window)
            best = max(best, count)
        if best > threshold:
            alerts.append((actor, best))
    return sorted(alerts, key=lambda a: a[0])


WINDOW = 5
THRESHOLD = 3
alerts = detect(EVENTS, WINDOW, THRESHOLD)
for actor, count in alerts:
    print(f"ALERT actor={actor} denies_in_window={count} (>{THRESHOLD})")
print(f"actors alerted: {len(alerts)}")
print(f"baseline u1 silent: {all(a != 'u1' for a, _ in alerts)}")

