ROLE_GRANTS = {
    "tenant_admin": {"export", "read"},
    "tenant_viewer": {"read"},
}

AUDIT = []


def authorize(session, action, target_tenant):
    name = session["name"]
    if not session["valid"]:
        AUDIT.append(f"deny authn actor={name} reason=invalid_session")
        return (401, "authn: invalid session")
    if action not in ROLE_GRANTS.get(session["role"], set()):
        AUDIT.append(f"deny rbac actor={name} action={action}")
        return (403, "rbac: role lacks action")
    if session["tenant"] != target_tenant:
        AUDIT.append(f"deny abac actor={name} subject_tenant={session['tenant']} object_tenant={target_tenant}")
        return (403, "abac: cross-tenant")
    AUDIT.append(f"allow actor={name} action={action} tenant={target_tenant}")
    return (200, "allow")


adminA = {"name": "a-admin", "role": "tenant_admin", "tenant": 42, "valid": True}
viewerA = {"name": "a-view", "role": "tenant_viewer", "tenant": 42, "valid": True}
stale = {"name": "ghost", "role": "tenant_admin", "tenant": 42, "valid": False}

CASES = [
    (adminA, "export", 7),
    (adminA, "export", 42),
    (viewerA, "export", 42),
    (stale, "export", 42),
]
for session, action, tenant in CASES:
    status, why = authorize(session, action, tenant)
    print(f"{session['name']:<8} {action} tenant={tenant} -> {status} {why}")
print("-- audit log (append-only) --")
for line in AUDIT:
    print(line)
